@RunWith(AndroidJUnit4.class)
public class IncrementalSyncDeviceTest {
 static final class Song{final String key;final byte[] bytes;final double cue;Song(String k,String b,double c){key=k;bytes=b.getBytes(StandardCharsets.UTF_8);cue=c;}JSONObject metadata()throws Exception{StringBuilder hash=new StringBuilder();for(byte b:java.security.MessageDigest.getInstance("SHA-256").digest(bytes))hash.append(String.format(Locale.ROOT,"%02x",b&255));return source().put("track_key",key).put("bytes",bytes.length).put("sha256",hash.toString()).put("preparation",new JSONObject().put("bpm",128).put("cue_in",0).put("cue_out",20).put("manual_cues",new JSONArray().put(new JSONObject().put("number",3).put("seconds",cue))));}}
 static JSONObject source()throws Exception{return new JSONObject().put("server_id","sync-server").put("station_id","sync-station").put("library_id","sync-library");}
 static JSONObject manifest(Map<Integer,Song> songs)throws Exception{JSONArray tracks=new JSONArray();for(Map.Entry<Integer,Song> e:songs.entrySet())tracks.put(new JSONObject().put("id",e.getKey()).put("title",e.getValue().key).put("track_key",e.getValue().key).put("extension","wav"));return source().put("tracks",tracks);}
 static JSONObject playlist(String name,String style,int... ids)throws Exception{JSONArray tracks=new JSONArray();for(int id:ids)tracks.put(id);return new JSONObject().put("id","stable-list").put("name",name).put("kind","smart").put("rules",new JSONObject().put("style",style).put("energy",.7)).put("tracks",tracks);}
 @Test public void incrementalSyncPreservesEditsAcrossReindexChangesFailureAndRemoval()throws Exception{
  Assume.assumeTrue(android.os.Build.VERSION.SDK_INT>=29);Context app=InstrumentationRegistry.getInstrumentation().getTargetContext();String name="SyncFixture-"+UUID.randomUUID();File sandbox=new File(app.getCacheDir(),name);assertTrue(sandbox.mkdir());Context context=new ContextWrapper(app){@Override public File getFilesDir(){return sandbox;}};
  AtomicReference<Map<Integer,Song>> songs=new AtomicReference<>(new LinkedHashMap<>());songs.get().put(10,new Song("alpha","AAAA",1));songs.get().put(20,new Song("beta","BBBB",1));AtomicInteger audioRequests=new AtomicInteger();AtomicBoolean rejectAudio=new AtomicBoolean();
  ServerSocket server=new ServerSocket(0,8,InetAddress.getByName("127.0.0.1"));Thread host=new Thread(()->{while(!server.isClosed())try(Socket socket=server.accept()){BufferedReader reader=new BufferedReader(new InputStreamReader(socket.getInputStream(),StandardCharsets.US_ASCII));String request=reader.readLine(),line;while((line=reader.readLine())!=null&&!line.isEmpty()){}String path=request.split(" ")[1];int id=Integer.parseInt(path.split("/")[4]);Song song=songs.get().get(id);boolean audio=path.endsWith("/audio");if(audio)audioRequests.incrementAndGet();boolean reject=audio&&rejectAudio.get();byte[] body=reject?new byte[0]:audio?song.bytes:song.metadata().toString().getBytes(StandardCharsets.UTF_8);OutputStream output=socket.getOutputStream();output.write(("HTTP/1.1 "+(reject?"500 Failed":"200 OK")+"\r\nContent-Length: "+body.length+"\r\nConnection: close\r\n\r\n").getBytes(StandardCharsets.US_ASCII));output.write(body);output.flush();}catch(Exception e){if(!server.isClosed())throw new RuntimeException(e);}});host.start();Set<String> mediaIds=new HashSet<>();
  try{
   CastClient client=new CastClient("http://127.0.0.1:"+server.getLocalPort(),"");File saved=RadioOffline.save(context,client,manifest(songs.get()),playlist(name,"Steady",10,20));assertEquals(2,audioRequests.get());List<MediaItem> first=RadioOffline.items(saved);MediaItem alpha=first.get(0);mediaIds.add(alpha.mediaId);Uri beta=first.get(1).localConfiguration.uri;
   PhoneCues.save(context,alpha,2,2500);context.getSharedPreferences("phone-track-details",0).edit().putFloat(alpha.mediaId+":bpm",129).commit();
   JSONObject local=RadioOffline.album(saved);local.getJSONObject("playlist").getJSONObject("rules").put("style","Chill");CatalogStore.put(new File(saved,"ampdj/catalog.ampdb"),"offline-playlist",local.toString());
   LinkedHashMap<Integer,Song> reindexed=new LinkedHashMap<>();reindexed.put(99,new Song("alpha","AAAA",3));reindexed.put(20,new Song("beta","BBBB",1));songs.set(reindexed);
   assertEquals(saved,RadioOffline.save(context,client,manifest(songs.get()),playlist(name,"Hype",99,20)));assertEquals("Unchanged audio must not be downloaded",2,audioRequests.get());assertEquals(1,RadioOffline.albums(context).size());
   JSONObject synced=RadioOffline.album(saved);assertEquals(0,synced.getJSONObject("sync_stats").getInt("downloaded"));assertEquals(2,synced.getJSONObject("sync_stats").getInt("reused"));assertEquals("Chill",synced.getJSONObject("playlist").getJSONObject("rules").getString("style"));assertTrue(synced.getJSONArray("conflicts").length()>=2);assertEquals(alpha.mediaId,RadioOffline.items(saved).get(0).mediaId);assertEquals(2500,PhoneCues.seconds(context,RadioOffline.items(saved).get(0),2));assertEquals(129,PhonePlaylists.bpm(context,alpha),0);
   int conflicts=synced.getJSONArray("conflicts").length();RadioOffline.save(context,client,manifest(songs.get()),playlist(name,"Hype",99,20));assertEquals(2,audioRequests.get());assertEquals(conflicts,RadioOffline.album(saved).getJSONArray("conflicts").length());
   LinkedHashMap<Integer,Song> expanded=new LinkedHashMap<>(songs.get());expanded.put(30,new Song("gamma","CCCC",1));songs.set(expanded);RadioOffline.save(context,client,manifest(songs.get()),playlist(name,"Hype",30,20,99));assertEquals(3,audioRequests.get());assertEquals("gamma",String.valueOf(RadioOffline.items(saved).get(0).mediaMetadata.title));
   LinkedHashMap<Integer,Song> changed=new LinkedHashMap<>(songs.get());changed.put(99,new Song("alpha","DDDD",3));songs.set(changed);String before=RadioOffline.album(saved).toString();rejectAudio.set(true);try{RadioOffline.save(context,client,manifest(songs.get()),playlist(name,"Hype",99,30));fail("Failed transfer must not publish");}catch(IOException expected){}assertEquals(before,RadioOffline.album(saved).toString());rejectAudio.set(false);
   RadioOffline.save(context,client,manifest(songs.get()),playlist(name,"Hype",99,30));assertEquals(5,audioRequests.get());assertEquals(alpha.mediaId,RadioOffline.items(saved).get(0).mediaId);assertEquals(2500,PhoneCues.seconds(context,RadioOffline.items(saved).get(0),2));assertEquals(2,RadioOffline.items(saved).size());try(InputStream in=context.getContentResolver().openInputStream(beta)){assertArrayEquals("BBBB".getBytes(StandardCharsets.UTF_8),in.readAllBytes());}
   Uri current=RadioOffline.items(saved).get(0).localConfiguration.uri;try(OutputStream out=context.getContentResolver().openOutputStream(current,"w")){out.write("XXXX".getBytes(StandardCharsets.UTF_8));}RadioOffline.save(context,client,manifest(songs.get()),playlist(name,"Hype",99,30));assertEquals("Changed local bytes must be repaired without deleting the original",6,audioRequests.get());assertEquals(2500,PhoneCues.seconds(context,RadioOffline.items(saved).get(0),2));
   RadioOffline.save(context,client,manifest(songs.get()),playlist(name,"Hype",99,30,20));assertEquals("Re-added membership reuses retained audio",6,audioRequests.get());assertEquals(first.get(1).mediaId,RadioOffline.items(saved).get(2).mediaId);
   RadioOffline.save(context,client,manifest(songs.get()),playlist(name,"Hype"));assertEquals(0,RadioOffline.items(saved).size());assertEquals(6,audioRequests.get());RadioOffline.save(context,client,manifest(songs.get()),playlist(name,"Hype",99,30,20));assertEquals(6,audioRequests.get());assertEquals(alpha.mediaId,RadioOffline.items(saved).get(0).mediaId);assertEquals(2500,PhoneCues.seconds(context,RadioOffline.items(saved).get(0),2));
   JSONObject mismatched=manifest(songs.get());for(int i=0;i<mismatched.getJSONArray("tracks").length();i++){JSONObject entry=mismatched.getJSONArray("tracks").getJSONObject(i);if(entry.getInt("id")==99)entry.put("track_key","different-song");}String currentSnapshot=RadioOffline.album(saved).toString();try{RadioOffline.save(context,client,mismatched,playlist(name,"Hype",99));fail("A server reindex during sync must not select the wrong song");}catch(IOException expected){assertTrue(expected.getMessage().contains("Library changed"));}assertEquals(currentSnapshot,RadioOffline.album(saved).toString());
   String snapshot=RadioOffline.album(saved).toString();LinkedHashMap<Integer,Song> cancelledSongs=new LinkedHashMap<>(songs.get());cancelledSongs.put(40,new Song("delta","EEEE",1));songs.set(cancelledSongs);AtomicBoolean cancel=new AtomicBoolean();try{RadioOffline.save(context,client,manifest(songs.get()),playlist(name,"Hype",40,99),new RadioOffline.Progress(){public void song(int i,int n,String t){if(i==2)cancel.set(true);}public boolean cancelled(){return cancel.get();}});fail("Cancellation must preserve the completed playlist");}catch(IOException expected){}assertEquals(snapshot,RadioOffline.album(saved).toString());assertEquals(1,new File(sandbox,"radio-offline").listFiles().length);
  }finally{server.close();host.join(2000);for(String id:mediaIds){android.content.SharedPreferences.Editor cues=context.getSharedPreferences("phone-cues",0).edit();for(int i=0;i<8;i++)cues.remove(id+":"+i).remove(id+":manual:"+i);cues.commit();context.getSharedPreferences("phone-track-details",0).edit().remove(id+":bpm").commit();}try(android.database.Cursor c=context.getContentResolver().query(MediaStore.Audio.Media.EXTERNAL_CONTENT_URI,new String[]{"_id"},MediaStore.Audio.Media.RELATIVE_PATH+"=?",new String[]{ManagedMusic.PATH+name+"/"},null)){if(c!=null)while(c.moveToNext())context.getContentResolver().delete(android.content.ContentUris.withAppendedId(MediaStore.Audio.Media.EXTERNAL_CONTENT_URI,c.getLong(0)),null,null);}try(java.util.stream.Stream<Path> paths=Files.walk(sandbox.toPath())){paths.sorted(Comparator.reverseOrder()).forEach(path->path.toFile().delete());}}
 }
 @Test public void mergeRetainsIndependentSettingsAndBothConflictingVersions()throws Exception{JSONArray conflicts=new JSONArray();JSONObject base=new JSONObject("{\"energy\":0.5,\"style\":\"Steady\"}"),phone=new JSONObject("{\"energy\":0.7,\"style\":\"Steady\"}"),desktop=new JSONObject("{\"energy\":0.5,\"style\":\"Hype\"}");JSONObject merged=(JSONObject)SyncMerge.merge(base,phone,desktop,"rules",conflicts);assertEquals(.7,merged.getDouble("energy"),0);assertEquals("Hype",merged.getString("style"));assertEquals(0,conflicts.length());desktop.put("energy",.9);merged=(JSONObject)SyncMerge.merge(base,phone,desktop,"rules",conflicts);assertEquals(.7,merged.getDouble("energy"),0);assertEquals(1,conflicts.length());assertEquals(.9,conflicts.getJSONObject(0).getDouble("desktop"),0);}
}
